INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(49300, 0, 493, 0, 0, 0, 'Moonglade', 'Moonglade is the sacred valley of the druids, a hidden forest ringed by high mountains between Felwood and Winterspring. The only road in runs through the tunnels of Timbermaw Hold. Druids have revered this place since ancient days: the demigod Cenarius once dwelt here, and here Malfurion Stormrage gathered the first druids into the Cenarion Circle. Its wooded hills hide barrow dens where druids sleep while their spirits walk the Emerald Dream, and in the Third War Tyrande Whisperwind fought her way here to wake Malfurion from his. In the years after Hyjal the glade was opened to druids of every race, tauren as well as night elf, under the guardianship of Keeper Remulos, son of Cenarius. The village of Nighthaven stands beside Lake Elune''ara, and its wardens allow no fighting, so Horde and Alliance meet here as guests of the Circle. Yet the peace has limits: tensions are growing between the druids of Moonglade and the Arch Druid of Darnassus.', 'warcraft.wiki.gg/wiki/Moonglade (Cenarius dwelt here in the War of the Ancients; Malfurion founded the Cenarion Circle here; mounds hide barrow dens; Third War, Tyrande wakes Malfurion; opened to all druid races after the Third War with Remulos as guardian; high mountains, only land route via Timbermaw Hold); quest 6762 and 1123 log text (Moonglade lies between Felwood and Winterspring, path out of Timbermaw Hold); npc_text 4753 (Dendrite: wardens trained to cease all hostilities); quest 5921 description (tensions between Staghelm and Remulos), quest 1123 description (growing tensions between Darnassus and the Circle); npc_text 14198 (Remulos: those who sacrificed their waking life in the Dream); darnassus.json 165700 (Malfurion has never returned from the Dream)'),
(49301, 1, 493, 1, 0, 0, 'Nighthaven', 'Nighthaven is the village of Moonglade and the seat of the Cenarion Circle, a quiet cluster of night elf halls and moonwells near the shore of Lake Elune''ara. Its welcome extends to every being who respects the authority and command of nature, on one condition: the balance must be kept, and the Moonglade Wardens are trained to end any hostility without question. Loganaar trains druids here and warns the young that one day the Emerald Dream will call them into a long hibernation. Keeper Remulos'' majordomo Rabine Saturna receives visitors, the eccentric archivist Umber keeps the Circle''s records, and merchants serve those passing through. Only druids may take the Circle''s flights to Thunder Bluff and Rut''theran Village.', 'npc_text 4753 (Dendrite: welcome to all who respect nature, preserve the balance, wardens cease hostilities); npc_text 4784 (Loganaar: the call of the Emerald Dream, hibernate for many years); npc_text 4913-4918 (druid-only flights to Rut''theran Village and Thunder Bluff); zone_areas.py area 2361: 22 Moonglade Warden 11822, Loganaar 12042, Malvor 12025 Herbalism Trainer, vendors, Rabine 11801, Umber 11939, moonwells 177273/177278/177280; warcraft.wiki.gg/wiki/Nighthaven (main village, night elven, home of the Cenarion Circle''s druids, on the lake shore); quest 1123 description (majordomo; Nighthaven the main village)'),
(49302, 1, 493, 2, 0, 0, 'Lake Elune''ara', 'Lake Elune''ara fills the heart of Moonglade, a broad sheet of clear water bearing the name of the moon goddess, with the village of Nighthaven on its shore and a warden of the Circle keeping watch along its banks. Young druids learning the aquatic form dive into its depths for a shrine bauble that crumbles away quickly, then race with it to the Shrine of Remulos before it fails, sometimes against other students on the same errand.', 'quests 28, 29 description (Shrine Bauble in the depths of Lake Elune''ara, decays rapidly, competing druids); quest 8447 description (waters of Lake Elune''ara dissolve the nightmares); creature_text 11832 groups 10-16, 17949 (Remulos leads to the lake; Malfurion appears); creature_text 11832 group 1 (rift opened above Lake Elune''ara); zone_areas.py area 656: Bauble Container 177785 x4; warcraft.wiki.gg/wiki/Lake_Elune''ara (large lake covering central Moonglade)'),
(49303, 1, 493, 3, 0, 0, 'Shrine of Remulos', 'West of Nighthaven stands the Shrine of Remulos, honoring the keeper who guides the Cenarion Circle in preserving nature and its balance. Remulos keeps watch there, and the warden Tajarri expects every visitor to behave as befits sacred ground, at least those who would rather not meet her scimitar. Young druids end their Trial of the Lake here, using the shrine bauble as a nod to the shrine''s importance within the Circle, and in the shrine''s presence they join the halves of the Pendant of the Sea Lion.', 'quest 29 reward text (Tajarri: Remulos guides the Circle, shrine a lasting tribute, bauble a nod to its importance); npc_text 4977 (Tajarri: sacred place, conduct yourself fittingly); quest 272 log text (pendant formed near the Shrine of Remulos); quest 13074 description (shrine closely tied with the dream; dangerous; beset by nightmares; acorns infused with restorative magic); quest 13073 description (Tirion sends for Remulos'' aid for Crusader Bridenbrad); gossip_menu_option 10215 (send me into the Emerald Dream to recover the acorns); DB: Remulos 11832 and Tajarri 11799 in area 2362; Nightmare Figment 30627 and Emerald Acorn 192676 in phase 2'),
(49304, 1, 493, 4, 0, 0, 'Stormrage Barrow Dens', 'The hills of southeastern Moonglade hold the Stormrage Barrow Dens, sacred chambers where night elf druids sleep while their spirits walk the Emerald Dream. Keeper Remulos watches over every druid who hibernates in the glade, and Loganaar, who trains the druids of Nighthaven, warns the young that the call of the Dream will one day take hold of them too, and that they will sleep for many years. The dens are named for Malfurion Stormrage, who slept within them through the ages until the Third War, when Tyrande Whisperwind fought her way into Moonglade to wake him.', 'warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens (sacred chambers of sleeping druids, named for Malfurion who slept within; body left in the den under the Circle''s care until the War Against the Nightmare; a den overrun by Nightmare creatures in TBC); creature_text 15491, 11832 group 5 (Eranikus seeks Malfurion in the Moonglade; not summoned on top of Malfurion); quest 10964 description (southernmost den, dreamwardens, Clintar); quest 10965 description and reward text, quest 10978 description (fragment of spirit, relics of Aviana, force that has invaded the Dream); quest 10955 and 10961 descriptions (Druids of the Talon taught flight; relics used to teach the ways of the stormcrow); zone_areas.py area 2363: Cenarion Dreamwarden 22835, Manifest Nightmare 22889, Phantasmal Lash 22902, Clintar 22834; quest 10955 description (Druids of the Talon taught flight before the orders joined the Circle; order dissolved), quest 10978 reward text (outside forces tampering with the Dream); quest 5922 description (Remulos keeps watch over all druids who hibernate there); npc_text 4784 (Loganaar: the call of the Emerald Dream, hibernate for many years)'),
(49305, 2, 493, 1, 0, 0, 'Keeper Remulos', 'Keeper Remulos, son of the demigod Cenarius, keeps Moonglade, the sacred heart of all druidic study, and his shrine stands west of Nighthaven. He welcomed the tauren into the Circle, and there is open tension between him and Arch Druid Fandral Staghelm. Of late he speaks of the Emerald Dream with grave unease. It has become a dangerous place, he says, and he grows ever more concerned for those who have given up their waking lives in Azeroth in hopes of saving it.', 'warcraft.wiki.gg/wiki/Remulos (son of Cenarius, brother of Zaetar, maintains Moonglade, welcomed the tauren, clashed with Fandral); quest 7066 description and reward text (Seed of Life; brother found peace; reborn; important to this war-torn land); desolace.json 40535 (Zaetar, Theradras, children killed their father); quest 6761 / darnassus.json 165709 (mistrust between the Arch Druid and Remulos); npc_text 14198 (Emerald Dream dangerous, those who sacrificed their waking life)'),
(49306, 2, 493, 2, 0, 0, 'Rabine Saturna', 'Rabine Saturna is Keeper Remulos'' majordomo, the night elf who welcomes all who come to aid the Circle on behalf of every denizen of the glade. To Horde volunteers he says that the tauren''s devotion to the tenets of Cenarius has earned the Horde a welcome here. To the Alliance, knowing the Arch Druid of Darnassus frowned on their coming, he promises safety from any ill-conceived repercussions, for the work serves the greater good. Umber calls him the den mother of their little bear camp. Behind his courtesy lies a private devotion: the memory of Millicent Serene, Milli as he calls her, the naturalist of Eldre''Thalas whose crowning creation is now being twisted into the Felvine.', 'quest 6762 and 1123 reward text (welcome on behalf of Remulos; tauren propensity for Cenarius; safe from ill-conceived repercussions); quest 6762 and 1123 description (Remulos'' majordomo); quest 6845 description (den mother of this little bear camp); gossip menus 5766-5768 (Millicent Serene, Milli), quest 5526 completion text; warcraft.wiki.gg/wiki/Rabine_Saturna (night elf, majordomo)'),
(49307, 2, 493, 3, 0, 0, 'Dendrite Starblaze', 'Dendrite Starblaze is the night elf druid in Nighthaven to whom the young druids of Darnassus and Thunder Bluff alike are sent. He greets every visitor in the Circle''s name and asks that the balance be kept. To the young he is guide and examiner at once: he sends them to the Great Bear Spirit, sets the trials of the lake and the sea lion, and answers cries for help from distant villages by sending students to do real work rather than staged tests. When a new druid first stands before him, he traces an unseen gesture in the air, an aura of power settles over him, and he murmurs to Father Cenarius that it has begun.', 'npc_text 4753 (greeting); quests 5921, 5922 reward text (invisible gesture, aura, Father Cenarius); quests 5929, 5930, 28, 29, 6121, 6126 (his lessons; no pre-planned trials, real work); quests 5931, 31, 6125 descriptions (We shall meet again / speak again); warcraft.wiki.gg/wiki/Dendrite_Starblaze (male night elf)'),
(49308, 2, 493, 4, 0, 0, 'Umber', 'Umber is the Cenarion Circle''s archivist in Nighthaven, a human among the night elves of the glade. He can lay hands on anything the Circle has stored away, provided the asker already knows what they are looking for, an arrangement he finds brilliant. Layo Starstrike in Silithus calls him touched but brilliant, a man who has saved tomes in worse shape than anyone thought could be saved. His manners are his own. He will tell a weary traveler frankly that they smell a bit ripe, and he has no love for anything bug-like, which suits him well enough: the horrors of Silithus can stay out there, and he can stay here with the books.', 'npc_text 6153 (archived information, know what you are looking for); quest 6844 description (brilliant, touched, salvaged tomes in far worse shape), completion text (you smell a bit ripe) and reward text (no pleasure for anything bug-like, stay here with the books); warcraft.wiki.gg/wiki/Umber (human)'),
(49309, 2, 493, 5, 0, 0, 'Tajarri', 'Tajarri is a night elf warden of Moonglade, posted at the Shrine of Remulos. Guarding the shrine is her duty and her privilege, she says, and she expects visitors to conduct themselves as guests on sacred ground, at least those who would rather not have her scimitar buried in them. She also has a hand in the teaching of young druids. Students who race up from Lake Elune''ara with a crumbling shrine bauble report to her to finish the Trial of the Lake, and she congratulates each one warmly before setting the Trial of the Sea Lion and sending them to ask the people of the glade where the two halves of the pendant may lie.', 'npc_text 4977 (sacred place; scimitar); quests 28, 29 reward text (duty and privilege to serve as a warden of the shrine); quests 30, 272 description (two halves, speak with the locals); warcraft.wiki.gg/wiki/Tajarri (night elf warden)'),
(49310, 2, 493, 6, 0, 0, 'Great Bear Spirit', 'In the northwest of Moonglade dwells the Great Bear Spirit, a wise and noble being the druids say has been part of Azeroth for as long as Azeroth has existed. It speaks without moving its mouth, its voice simply heard, and every druid of the Claw comes to it at the start of the path. It represents the strength that bolsters a young druid, and teaches two lessons. Strength of body is power and swiftness, the bear''s great girth hiding a lithe agility and a sharp mind. Strength of heart is the resolve to act from pure intent, the conviction of a mother bear guarding her young. Keeping the balance, it warns, is never mere complacency.', 'quests 5929, 5930 description (northwest Moonglade, wise and noble being, tutor and mentor of all druids); quests 5931, 5932 reward text (part of Azeroth as long as Azeroth has existed); npc_text 4719 (voice without the creature speaking); gossip menus 3881, 3883, 3884, 3885 (strength of body and heart, mother bear, balance not complacency); DB: spawn 8068,-2284 resolves to area 493'),
(49311, 2, 493, 7, 0, 0, 'Bunthen Plainswind and Silva Fil''naveth', 'Two flight masters stand together in Nighthaven, and they serve druids alone. Silva Fil''naveth, a night elf, offers the Cenarion Circle''s flight to Rut''theran Village below Darnassus, while her tauren counterpart Bunthen Plainswind carries druids to Thunder Bluff, and each sends the other''s people to their partner. In that small courtesy lies the glade''s whole purpose: night elf and tauren side by side in the Circle''s service. Anyone else who asks for a ride is told plainly that they are not a druid. Other travelers must make do with the hippogryph master Sindrayl and the wind rider master Faustron, who keep their own posts out in the open glade beyond the village.', 'npc_text 4913-4918 (You''re not a druid; flights to Rut''theran Village and Thunder Bluff courtesy of the Cenarion Circle; counterparts); creature_template 11798, 11800 subnames (Thunder Bluff / Darnassus Flight Master), both in area 2361; DB: Sindrayl 10897 (Hippogryph Master, template 80) and Faustron 12740 (Wind Rider Master, template 29) spawned in area 493 outside Nighthaven'),
(49312, 3, 493, 1, 0, 0, 'The Way of the Claw', 'When a young druid is ready to learn the shape of the bear, the trainer, Mathrengyl Bearwalker in Darnassus or Turak Runetotem in Thunder Bluff, teaches the spell that carries druids to Moonglade and sends the student to Dendrite Starblaze. The night elf is reminded that all druids are welcome there, whatever the tensions between the Arch Druid and Keeper Remulos; the tauren is told that Remulos watches over every druid who sleeps in the glade. Dendrite greets the student with a quiet word to Father Cenarius that it has begun, and sets them on the path of the bear: first they must seek out the Great Bear Spirit in the northwest of the glade, mentor to every druid, and learn what it will teach.', 'quests 5923-5928 (Heeding the Call, to Mathrengyl or Turak); quests 5921, 5922 description and reward text; quests 5929, 5930 description and reward text; gossip menu 3885 (your strength will be tested); quests 5931, 5932 description and reward text; quests 6001, 6002 description and reward text (Moonkin Stone east of Auberdine / west of Taurajo, Lunaclaw)'),
(49313, 3, 493, 2, 0, 0, 'The Trials of the Lake and the Sea Lion', 'The aquatic form is a blessing that must be earned. Druids who have grown into worthy protectors of nature are sent from Darnassus and Thunder Bluff to Dendrite Starblaze, who sets them two trials. The first tests work in water under pressure: the student dives into Lake Elune''ara for a shrine bauble, which decays rapidly, and must carry it to the Shrine of Remulos before it fails, perhaps racing other druids on the same errand, then use it there and report to the warden Tajarri, one of Moonglade''s most trusted.', 'quests 26, 27 description and reward text (aquatic form must be earned; two trials); quests 28, 29 description and reward text; quests 30, 272 description and reward text (agility and endurance, ask the locals, neither can exist without the other); quests 31, 5061 (return to Turak or Mathrengyl)'),
(49314, 3, 493, 3, 0, 0, 'Lessons Anew', 'Druids can purge poison with a single incantation, a gift of Cenarius not to be taken lightly. Before they learn it, the trainers of Darnassus and Thunder Bluff send their students to Dendrite Starblaze to learn what poison means for those without that power. There are no staged trials here, for real calls for help have reached Moonglade. In Auberdine, Alanndarian Nightsong cannot stop a sickness among the deer of Darkshore, and Dendrite suspects the Cliffspring Falls, the region''s main source of drinking water. At the Crossroads, Tonga Runetotem faces the same among the gazelles of the northern Barrens, and the suspicion falls on the pools atop Dreadmist Peak, where the Burning Blade dwell.', 'quests 6121, 6126 description and reward text (gift of Cenarius; no pre-planned trials; real work); quests 6122, 6127 description and reward text (Cliffspring Falls, Dreadmist Peak, Burning Blade, disgusting water); quests 6123, 6128 (earthroot, lunar fungus from moonkin caves, kodo horns); quests 6124, 6129 reward text (unwitting victims of a greater taint; those in Darnassus who ignore; balance transcends artificial racial barriers); quests 6125, 6130'),
(49315, 3, 493, 4, 0, 0, 'The Fruit of Fertility', 'Agents of the Cenarion Circle have brought Rabine Saturna troubling news from Eldre''Thalas, the ruin now called Dire Maul. Long ago a night elf naturalist there, Millicent Serene, willed the power of nature into artifacts, and her crowning work was the Fruit of Fertility, a vibrant vine grown from a specially prepared moonwell whose aura of protection and growth made all of Eldre''Thalas flourish. The Circle believed it destroyed in the War of the Ancients. It survived, and the demon Alzzin the Wildshaper is corrupting it into the Felvine. Rabine will not let that corruption run its course, for the world''s sake and for Milli''s memory. So vile a thing can only be held in a Reliquary of Purity, and he knows one lay in the ruins of Southwind Village in Silithus many years ago.', 'gossip menus 5764-5768 (Rabine: agents uncovered disturbing information; Millicent Serene; Fruit of Fertility; moonwell; War of the Ancients; Felvine; Alzzin; Milli); creature_text 11801 (threat of the Felvine); quest 5527 description, completion and reward text (Reliquary of Purity at Southwind; kept it a secret; malfeasant demon); quest 5526 description, completion and reward text (seal the shard; study it; hero of the Cenarion Circle)'),
(49316, 3, 493, 5, 0, 0, 'The Redemption of Eranikus', 'The champion who seeks the green shard of the Scepter of the Shifting Sands must recover it from Eranikus, a dragon of Ysera''s flight. In the Sunken Temple, Malfurion warned that the power of the Old Gods had twisted him into a tyrant of the Dream who would never give the shard up freely, and that there was only one way: bring Eranikus into the world. A wisp outside Darnassus carried word to Tyrande and sent the champion on to Keeper Remulos. Eranikus could never be pulled from the Dream against his will, Remulos explains, but he wishes to come, for he means to destroy Malfurion''s sleeping body, and with it one of the Dream''s mightiest allies. First, fragments of the Nightmare''s corruption must be taken from the dragonkin at the four dream portals.', 'quest 8733 description, creature_text 15362 (Malfurion in the Sunken Temple: bring him into this world); quest 8734 description and reward text; quest 8735 description; quest 8736 description and reward text; creature_text 11832 groups 0-9, 15491, 15628, 15633 (rift above the lake; not on top of Malfurion; Shan''do Stormrage; Tyrande''s prayers; return to the Dream; shard); warcraft.wiki.gg/wiki/Remulos (Tyrande arrives with priestesses)'),
(49317, 3, 493, 6, 0, 0, 'Shrouded in Nightmare', 'Four dragons of Ysera''s flight have come forth from the dream portals of Duskwood, the Hinterlands, Ashenvale and Feralas, corrupted and sick with nightmare: Taerar, Lethon, Ysondre and Emeriss. Those who bring one down find an object engulfed in nightmares, corruption seeping from it, that seems to tie the dragons to the Dream itself. It cannot be read by just anyone. Only a druid of great power could decipher its meaning, perhaps one of the druids of Moonglade, or of Cenarion Hold in the south.', 'quest 8446 description (corruption seeps; link with the dragons coming forth from the Dream; druids of the Moonglade) and reward text (recent failures to delve into the Dream); quest 8447 description and reward text (waters of Lake Elune''ara; Malfurion''s ring); creature_text 17949 (Malfurion''s words), 11832 groups 10-17; DB: item 20644 Nightmare Engulfed Object starts 8446, drops 100% from Ysondre 14887, Lethon 14888, Emeriss 14889, Taerar 14890'),
(49318, 3, 493, 7, 0, 0, 'The Journal Under the Chitin', 'Rabine Saturna''s call to Horde and Alliance alike leads beyond Tanaris and Un''Goro, to the wasteland of Silithus. Few know, he says, that the night elves once fought a malign and alien power there; it was sealed away, but the Circle suspects that something now works to stir it. He sends volunteers with a letter to Layo Starstrike, one of the Circle''s agents, at Valor''s Rest, the resting place of those who fell in the wastes, and promises that Layo''s trust will follow the letter.', 'quest 1124 description and reward text; quest 6844 description and reward text (Encrusted Silithid Object to Umber); quest 6845 description and reward text; quest 1185 reward text (journal in an ancient dialect of Darnassian; den mother excited); quest 6845 description (never leave the den mother waiting, doused in honey) and reward text (more secrets to uncover from Silithus)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(49302, 1, 0, 255, 'Its waters have a deeper virtue. Keeper Remulos uses them to dissolve the nightmares that cling to things touched by the corruption in the Dream, and he means to cleanse one such object at its shore, hoping it might explain his recent failures to reach into the Dream.', 'quest 8447 description (waters of Lake Elune''ara dissolve the nightmares); quest 8446 reward text (recent failures to delve into the Dream)'),
(49302, 2, 0, 255, 'As the taint washed away in the lake, the spirit of Malfurion Stormrage appeared before Remulos. The object had carried his message, and he had known it would find its way to his old friend. The two spoke of the Nightmare at the shore until the Dream pulled Malfurion back.', 'creature_text 11832 groups 10-16 (Remulos leads to the lake; Malfurion!); creature_text 17949 (Malfurion''s words; drawn back)'),
(49302, 3, 0, 255, 'Above this lake, too, Remulos chose to open a rift into the Dream, far from where Malfurion sleeps, so that the corrupted dragon Eranikus could be drawn into the waking world and redeemed rather than destroyed.', 'creature_text 11832 group 1 (rift opened above Lake Elune''ara), group 5 (not summoned on top of Malfurion); quest 8736 description (redeem him, not destroy him)'),
(49303, 1, 13, 255, 'When Tirion Fordring sought the keeper''s help for a stricken crusader in Icecrown, Remulos named his shrine among the places in the glade most closely tied to the Emerald Dream. From here he sends a willing champion into the Dream for acorns infused with restoring magic, warning that this way in is dangerous and that nightmares lie in wait.', 'quest 13074 description (shrine closely tied with the dream; dangerous; beset by nightmares; acorns infused with restorative magic); quest 13073 description (Tirion sends for Remulos'' aid for Crusader Bridenbrad); gossip_menu_option 10215 (send me into the Emerald Dream)'),
(49304, 1, 0, 255, 'Malfurion Stormrage has not gone far. His spirit fights within the Emerald Dream as one of its mightiest allies, while his sleeping body lies here in the Circle''s keeping. That is why the corrupted dragon Eranikus longs to cross into the waking world: to destroy Malfurion''s body and leave the Dream to the Nightmare.', 'quest 8734 reward text (living manifestation of Malfurion; one of the most powerful allies of the Dream; the Nightmare would consume all); creature_text 11832 group 2, 5 and 15491 groups 0, 2 (Malfurion''s physical manifestation in the Moonglade); warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens (body left in the den under the Circle''s care)'),
(49304, 2, 8, 255, 'In these days the southernmost den is under guard. Cenarion dreamwardens stand watch over the druid Clintar Dreamwalker, who sleeps there, while manifest nightmares and phantasmal lashes stalk the chamber around him.', 'zone_areas.py area 2363: Cenarion Dreamwarden 22835, Manifest Nightmare 22889, Phantasmal Lash 22902, Clintar 22834; quest 10964 description (southernmost den, dreamwardens)'),
(49304, 3, 8, 255, 'Morthis Whisperwing, once of the Druids of the Talon who taught young druids the mysteries of flight, sends his apprentice with a ward to wake Clintar, guardian of the relics used to teach the ways of the stormcrow. Clintar wakes haggard and fearful. The Dream''s grasp on him is strong, so a fragment of his spirit must guide the search for the Relics of Aviana, and the horrors in his chamber, he says, are but an echo of the reality inside the Dream.', 'quest 10955 description (Druids of the Talon taught flight; order dissolved); quest 10961 description (relics entrusted to an ancient druid); quest 10964 description and reward text; quest 10965 description (fragment of spirit; echo of the reality inside the dream); item 32074 Relics of Aviana'),
(49304, 4, 8, 255, 'With the relics recovered, Clintar must turn his whole attention back to the fight, for he believes a force from outside has invaded the Emerald Dream. The dreamwarden Lurosa sends word of it to Morthis, hoping he can learn what Clintar struggles against.', 'quest 10965 reward text (Clintar under attack in the Dream); quest 10978 description (the force that has invaded the Emerald Dream); DB: 10965 ends and 10978 starts with Dreamwarden Lurosa 22837'),
(49305, 1, 0, 255, 'A seed carried from Maraudon brought him word of his brother Zaetar, long dead at the hands of the centaur, his own misbegotten children. Remulos had thought him lost to arrogance and anger. Told that Zaetar''s spirit lives on there, its remains nourishing new life, he took the seed as proof that his brother had found peace and been reborn into nature, and he senses it will one day matter to this war-torn land.', 'quest 7066 description (misbegotten centaur, my sons and daughters; first seed from the life my remains nourished) and reward text (finally found peace; arrogance and anger; reborn; war-torn land)'),
(49312, 1, 0, 255, 'The Great Bear Spirit teaches strength of body and strength of heart, and sends the student away with its blessing and a warning that their strength will one day be tested. Dendrite senses a new wisdom in them, a strength and knowing intent not yet focused, and sends them home to the trainer who sent them.', 'gossip menus 3881, 3883, 3884, 3885; quests 5929, 5930 reward text (wisdom not present before; intent not yet focused); quests 5931, 5932 description'),
(49312, 2, 0, 255, 'Back in Darnassus, Mathrengyl explains that the Great Bear Spirit has been part of Azeroth for as long as Azeroth has existed, and that druids rely on its wisdom and power. Then he sets the last test. In the moonkin cave nearest Auberdine stands a Moonkin Stone, and its defender Lunaclaw comes forth only when Cenarion moondust is laid upon it. Its strength must be faced before the way of the Claw is learned.', 'quest 5931 reward text; quest 6001 description (moonkin caves east of Auberdine, Moonkin Stone, Lunaclaw, Cenarion Moondust)'),
(49312, 3, 0, 255, 'Back in Thunder Bluff, Turak explains that the Great Bear Spirit has been part of Azeroth for as long as Azeroth has existed, and that the tauren listen closely to such spirits. Then he sets the last test. West of Taurajo, where the Barrens give way to Mulgore, lies a Moonkin Stone, and its defender Lunaclaw comes forth only when Cenarion lunardust is laid upon it. Its strength must be faced before the way of the Claw is learned.', 'quest 5932 reward text; quest 6002 description (west of Taurajo before Mulgore, Moonkin Stone, Lunaclaw, Cenarion Lunardust)'),
(49313, 1, 0, 255, 'Using the bauble at the shrine honors its importance within the Circle, and Tajarri congratulates each student who succeeds. Then she sets the second trial, which tests understanding of the form itself. The Pendant of the Sea Lion must be made whole from two halves, one holding the sea lion''s agility in the water, the other its endurance, and the people of the glade hold the clues to where they lie.', 'quests 28, 29 reward text; quests 30, 272 description'),
(49313, 2, 0, 255, 'Joined at the shrine, the pendant carries its lesson: neither agility nor endurance can stand without the other, and neither without the will to embrace the aspect of the sea lion. Dendrite sends the student home with it, and the trainer there completes the lesson.', 'quests 30, 272 reward text (neither can exist without the other); quests 31, 5061 description'),
(49314, 1, 0, 255, 'Alanndarian finds the water from Cliffspring Falls disgusting. Something is fouling Darkshore''s whole water table, and sick deer are seen far from the river, yet she senses that something else is at work as well. The tainted water itself will be the base of her curative salve, with earthroot for healing and, for potency, lunar fungus from the caves to the east, where the moonkin have grown irritable.', 'quest 6122 reward text (disgusting, water table, sick deer all over, something else at work); quest 6123 description (water the base of the salve, earthroot, lunar fungus in caves to the east, irritable moonkin)'),
(49314, 2, 0, 255, 'Tonga finds the water from Dreadmist Peak disgusting. Something is fouling it and beginning to wreck the northern Barrens, and sick gazelles are seen all across the land north of the road, yet he senses that something else is at work as well. The tainted water itself will be the base of his curative salve, with earthroot for healing and, for potency, whole kodo horns, not mere chips, from the kodos of the northern Barrens.', 'quest 6127 reward text (disgusting, wrecking the northern Barrens, sick gazelles north of the road, something else at work); quest 6128 description (water the base of the salve, earthroot, kodo horns not chips, northern Barrens kodos)'),
(49314, 3, 0, 255, 'When ten deer are cured, Dendrite calls them unwitting victims of a greater taint and corruption spreading through all the land. There are those in Darnassus who see the threat, he says, and those who ignore the growing signs, and he hopes his student will not be one who puts on blinders.', 'quest 6124 reward text'),
(49314, 4, 0, 255, 'When ten gazelles are cured, Dendrite calls them unwitting victims of a greater taint and corruption spreading through all the land. The student, like the elders of Thunder Bluff, has shown that the need for balance transcends artificial racial barriers, and has proven a friend of nature and the Circle.', 'quest 6129 reward text'),
(49315, 1, 0, 255, 'The reliquary comes back from Southwind, and Rabine admits he had known of it for a while. With turmoil rising in Silithus he had kept it secret, since prying would only rouse the suspicions of the Circle''s enemies. Now he asks for the rest: to face Alzzin in the east of Dire Maul and, when the demon falls, seal a shard of the Felvine inside.', 'quest 5527 completion text (known for a little while; kept secret to avoid rousing suspicions) and reward text; quest 5526 description'),
(49315, 2, 0, 255, 'The sealed reliquary reaches Nighthaven. With it the Circle can remove a corrupting threat from the world and study it under its own watch, perhaps finding new means against the taint, and Rabine knows Milli would have had it no other way. The war is far from over, he says, but a great battle has been won, and its bearer is welcomed as a hero of the Cenarion Circle.', 'quest 5526 completion and reward text'),
(49316, 1, 0, 255, 'Remulos is bound by duty and honor to Malfurion, though he wonders whether the world is ready for what they are about to invoke. Through the fragments he finds the Nightmare''s origin and opens the rift above Lake Elune''ara, well away from Malfurion. Eranikus is to be redeemed, not destroyed: his blows must be weathered and Nighthaven saved until Tyrande arrives.', 'quest 8735 reward text; quest 8736 description; creature_text 11832 groups 0-3'),
(49316, 2, 0, 255, 'Eranikus demanded Shan''do Stormrage and loosed his nightmare servants on Nighthaven, while its defenders held them off and spared the dragon. Then Tyrande came. Her prayers drove out the madness, and the redeemed Eranikus returned to the Dream to aid Malfurion, Cenarius and Ysera, leaving the shard behind, while Remulos gave the champion armaments from Ysera herself for the war against the Qiraji.', 'creature_text 15491, 11832 groups 4-9, 15628, 15633; quest 8736 reward text (redeemed; ally to Malfurion and my father; armaments from Ysera; the Qiraji)'),
(49317, 1, 0, 255, 'In Moonglade, Keeper Remulos took the object, saying it might explain his recent failures to reach into the Dream, and led its bearer down to Lake Elune''ara, whose waters dissolve such nightmares.', 'quest 8446 reward text; quest 8447 description; creature_text 11832 groups 10-11'),
(49317, 2, 0, 255, 'As the taint washed away, Malfurion Stormrage appeared to his old friend, the message having found its way to him. A new foe fought them in the Dream, Malfurion said, born of an ancient evil: Ysera''s noble brood had fallen to the old whisperings, and the Nightmare sought a new host on Azeroth. Cenarius fought at his side, he said, and Illidan brooded on his throne in Outland, sunk in madness. Then Malfurion was drawn back, asking Remulos to tell Tyrande he was safe and would return. His signet ring went to the messenger.', 'creature_text 17949 (Malfurion''s words), 11832 groups 12-17; quest 8447 reward text (Malfurion''s ring)'),
(49318, 1, 0, 255, 'In time the work there sends one of them home to Nighthaven with a book-shaped thing pried from a silithid hive and crusted in chitin. Umber the archivist promises to crack its shell and share what he finds, and sends the bearer on to the den mother of their little bear camp, Rabine, who must never be kept waiting unless one cares to be doused in honey.', 'quest 6844 description and reward text (book shaped; crack this shell); quest 6845 description (den mother, honey)'),
(49318, 2, 0, 255, 'Rabine has had word of the bearer''s return and offers the Circle''s gratitude in person. No doubt, he says, Silithus holds more secrets yet, and the delivery to Umber should prove most interesting once it is opened.', 'quest 6845 reward text'),
(49318, 3, 0, 255, 'Umber keeps his word. The object was indeed a book, a journal in a very ancient dialect of the Darnassian tongue. Its study will take him a long while, but he declares it extremely valuable to the Circle, and the den mother is thrilled.', 'quest 1185 reward text');
